/**
 * PKM V2.13 — First-Party Domain Quality Framework & Audit Ledger
 *
 * Evaluates every first-party domain against 20 standard quality vectors:
 * Purpose clarity, Fast primary action, Creation quality, Detail quality, List/view quality,
 * Search, Saved Views, Relations, Context, Home, Attention, Activity, Review,
 * Temporal behavior, Mobile, Accessibility, Privacy, Export, Sync, Backup, Performance.
 *
 * Strict Classification:
 * 'Excellent' | 'Good' | 'Needs refinement' | 'Missing but applicable' | 'Not applicable'
 * No arbitrary numeric scores or AI slop.
 */

export type DomainQualityRating =
  | 'Excellent'
  | 'Good'
  | 'Needs refinement'
  | 'Missing but applicable'
  | 'Not applicable';

export type FirstPartyDomainId =
  | 'people'
  | 'projects'
  | 'goals'
  | 'areas'
  | 'tracking'
  | 'routines'
  | 'learning'
  | 'library'
  | 'finance'
  | 'health'
  | 'travel'
  | 'assets'
  | 'decisions'
  | 'inbox';

export interface DomainEvaluationVector {
  vector: string;
  rating: DomainQualityRating;
  notes: string;
}

export interface DomainQualityAuditRecord {
  domainId: FirstPartyDomainId;
  name: string;
  corePurposeQuestion: string;
  primaryAction: string;
  vectors: Record<string, DomainQualityRating>;
  overallStatus: 'Excellent' | 'Good' | 'Needs refinement';
  strengths: string[];
  refinementsInV2_13: string[];
  privacyPosture: 'Standard' | 'Restrained' | 'Strict / Conservative';
  exportFormats: string[];
}

